/**
 * omp console control API. Owned by main: writers request changes, they do not edit this file.
 *
 * Two planes:
 * - Control plane (this file): daemon HTTP+JSON under `/api`, used to list, create, resume and
 *   fork sessions, obtain a room link, read health, and register push subscriptions.
 * - Data plane: omp collab frames (`@oh-my-pi/pi-wire` GuestFrame/HostFrame) sealed end to end,
 *   relayed by the daemon at `/r/<roomId>?role=host|guest`. omp console never changes those frames; a
 *   console-specific need is met by a new control endpoint or an additive frame agreed with main.
 *
 * Auth: the daemon binds 127.0.0.1 only. Every request must carry a `Host` (and `X-Forwarded-Host`, if
 * present) on the daemon's allowlist (`localhost`, `127.0.0.1`, `[::1]` plus `--allow-host` names), and a
 * request with an `Origin` header must have an origin equal to the request's host (421 / 403 otherwise: DNS
 * rebinding and cross-site requests). It is then accepted when it carries no proxy headers, or carries
 * `Tailscale-User-Login` equal to the configured owner (set by `tailscale serve`). Clients must be
 * same-origin with the daemon.
 */
import type { LiveModeStatus, LoopModeStatus, VibeModeStatus } from "./wave3";
import type { OvernightSummary, StartOvernightRequest } from "./overnight";

export const OMP_CONSOLE_API_VERSION = 1;

/** Externally visible lifecycle of an AgentSession, including workerless sleep and wake transitions. */
export type SessionState = "starting" | "waking" | "idle" | "streaming" | "asking" | "stopped" | "crashed" | "asleep";

export interface SessionSummary {
	/** omp session id (stable across resume). */
	id: string;
	title?: string;
	/** Internal sessions (knowledge quick-ask) are excluded from the normal live and recent lists. */
	hidden?: boolean;
	/** Pinned by the owner (shown first, kept in the offline cache, never auto-slept). */
	pinned?: boolean;
	/** Frozen sessions refuse new prompts and commands (a move in progress, spec 9). */
	frozen?: boolean;
	/** Agent loops in this worker process are paused at their next safe boundary; distinct from frozen. */
	paused?: boolean;
	/** Epoch ms when this worker's pause began. */
	pausedAt?: number;
	cwd: string;
	/** Absolute path of the session file; absent for sessions that were never persisted. */
	sessionFile?: string;
	/** Set on persisted sessions not hosted by this daemon; opening creates a copy. */
	source?: "terminal";
	/** Whether the saved session's project folder still exists. */
	cwdExists?: boolean;
	model?: string;
	thinkingLevel?: string;
	state: SessionState;
	createdAt: number;
	lastActivityAt: number;
	/** Present while a worker hosts the session. */
	roomId?: string;
	/** Top-level agent id of the worker's session; used to scope the subagent tree. */
	rootAgentId?: string;
	/** Live subagents under rootAgentId. */
	agentCount: number;
	goalActive: boolean;
	/** Objective text of the active goal, when one is set (filled from the worker's goal runtime). */
	goalObjective?: string;
	/** Worker-owned autonomous repeat state. */
	loopMode?: LoopModeStatus;
	/** Worker-owned Vibe mode state and live workers. */
	vibeMode?: VibeModeStatus;
	/** Overnight lifecycle state remains visible after its terminal report is stored. */
	overnight?: OvernightSummary;
	/** Live worker-owned realtime voice session state. */
	liveMode?: LiveModeStatus;
	/** True when the session is blocked on an `ask` answer. */
	awaitingAnswer: boolean;
	/** Question the session waits on, when `awaitingAnswer` (first ~200 characters). */
	pendingQuestion?: string;
	/** `approval` when the options are a permission decision, `ask` for a question to the user. */
	pendingKind?: "ask" | "approval";
	/** When the running turn began (streaming or waiting on an answer); absent while idle. */
	turnStartedAt?: number;
	/** Archive metadata; present only for rows in `ListSessionsResponse.archived`. */
	archivedAt?: number;
}

/** Oldest eligible idle worker offered when the daemon is at its worker limit. */
export interface SleepCandidate {
	id: string;
	title: string;
	idleMinutes: number;
}

/** `GET`/`PUT /api/settings/sleep` use minutes; zero disables automatic sleep. */
export interface SleepSettingsRequest {
	minutes: number;
}

export interface SleepSettingsResponse {
	minutes: number;
}

/** `POST /api/sessions/:id/sleep` response. */
export interface SleepSessionResponse {
	state: "asleep";
}

/** `POST /api/sessions/:id/abort` stops the running turn without a guest connection: 202 with this body, 409 when idle. */
export interface AbortSessionResponse {
	aborted: true;
}
/** `POST /api/sessions/:id/restart`; active work requires explicit restartAnyway confirmation. */
export interface RestartSessionRequest {
	restartAnyway?: boolean;
}


export interface ListSessionsResponse {
	live: SessionSummary[];
	/** Recent persisted sessions without a worker (SessionManager.listAll), newest first, capped by `?limit=` (default 100, max 1000; 400 otherwise). */
	recent: SessionSummary[];
	/** Archived sessions, newest archive first, capped at 200. Optional for older peer daemons. */
	archived?: SessionSummary[];
}
/** `PUT /api/sessions/:id/archive`; active work needs explicit `stopIfLive: true` confirmation. */
export interface ArchiveSessionRequest {
	stopIfLive?: boolean;
}

/** Archive metadata returned by `PUT /api/sessions/:id/archive`. */
export interface ArchiveSessionRecord {
	archivedAt: number;
	title?: string;
	cwd?: string;
	sessionFile?: string;
	lastActivityAt?: number;
}

/**
 * `POST /api/sessions/:id/trash`: deletes an archived, stopped session by moving its transcript (and its subagent
 * folder) to the Trash on macOS, or to the daemon's `trash/` folder elsewhere. `trashedTo` is where it went; null when
 * the transcript was already gone and only the archive entry was removed.
 */
export interface TrashSessionResponse {
	trashedTo: string | null;
}

export interface CreateSessionRequest {
	cwd: string;
	/**
	 * Create `cwd` (and missing parents) just before starting a new session. Accepted only when `cwd` lies under the
	 * daemon's knowledge or projects root and the request neither resumes nor forks.
	 */
	createDirectory?: boolean;
	/**
	 * Restrict the session to these tool names (omp's restricted tool set). Set only by the daemon itself (the hidden
	 * agenda session); not accepted from `POST /api/sessions`.
	 */
	toolAllowlist?: readonly string[];
	/** Model selector or role alias, as accepted by omp. */
	model?: string;
	/** Resume a persisted session file instead of starting a new one. */
	resumeSessionFile?: string;
	/** Fork from a live or persisted session. */
	forkFrom?: { sessionFile: string; entryId?: string };
	/** Title set at creation (omp's title generator is not run). */
	title?: string;
	/** Internal session, excluded from the session lists (see `SessionSummary.hidden`). */
	hidden?: boolean;
	/** Sent as the first prompt once the worker is ready (workspace handoff, move handoff). */
	handoff?: string;
	/** Overnight controller options and the first task prompt. */
	overnight?: StartOvernightRequest;
	/** Repeated creates with the same key return the same live session instead of a new one. */
	idempotencyKey?: string;
}

/** `POST /api/sessions` answers 201 with this once the worker reported `ready`. */
export type CreateSessionResponse = SessionSummary;

export type RoomPermission = "full" | "view";

export interface RoomLinkResponse {
	roomId: string;
	/** Collab link the web client connects with: relay URL, room id and key in the fragment. */
	link: string;
	/** `full` may prompt, abort and answer asks; `view` is read-only. */
	permission: "full" | "view";
}

/**
 * `POST /api/sessions/:id/room` body (optional; empty body means `full`).
 * A worker still in `starting` answers 409 `conflict`; clients retry.
 */
export interface RoomLinkRequest {
	/** `view` returns a link carrying the bare room key (no write token). */
	permission?: "full" | "view";
}

/**
 * `POST /api/sessions/:id/agents/:agentId/model` changes the model of the root agent or one running subagent of
 * a live session (session-only override; the persisted default is untouched). 404 for an unknown session or
 * agent, 409 when the agent has no live session, 400 for an unresolvable selector.
 */
export interface SetAgentModelRequest {
	/** Selector as accepted by `--model`: `provider/id`, fuzzy name, or role alias. */
	selector: string;
}

export interface SetAgentModelResponse {
	agentId: string;
	/** `provider/id` now active on the agent. */
	model: string;
	thinkingLevel?: string;
}

/** One selectable model: `selector` is what every `selector` field in this API accepts. */
export interface ModelOption {
	selector: string;
	provider: string;
	label: string;
	/** Whether the shared omp login or key can use it right now. */
	available: boolean;
}

/** `GET /api/models`. `roles` maps a role alias (default, smol, plan, ...) to its configured selector. */
export interface ListModelsResponse {
	models: ModelOption[];
	roles: Record<string, string>;
}

/** A task-agent profile (agent definition) and how its model is chosen for new spawns. */
export interface AgentProfileSummary {
	name: string;
	source: "bundled" | "user" | "project";
	description?: string;
	/** Model selectors from the definition's frontmatter, in priority order. */
	definitionModels: string[];
	/** `task.agentModelOverrides[name]`, when set. */
	override?: string;
	/** What a spawn of this profile would resolve to now, when known. */
	effectiveModel?: string;
}

/** `GET /api/profiles`. */
export interface ListProfilesResponse {
	profiles: AgentProfileSummary[];
	roles: Record<string, string>;
}

/**
 * `PUT /api/profiles/:name/model` sets (or with `selector: null` clears) `task.agentModelOverrides[name]` through
 * omp's Settings, so it persists in the user's config and applies to new spawns in every worker.
 * `PUT /api/model-roles/:role` sets `modelRoles[role]`. Both answer 204; unknown name/role 404; unresolvable
 * selector 400.
 */
export interface SetProfileModelRequest {
	selector: string | null;
}

export interface SetModelRoleRequest {
	selector: string;
}

export interface WorkerHealth {
	sessionId: string;
	pid: number;
	state: SessionState;
	rssBytes: number;
	startedAt: number;
	lastEventAt: number;
	/** Set while streaming and no event arrived for `stalledAfterMs`. */
	stalled: boolean;
	restarts: number;
}

export interface DaemonHealth {
	version: number;
	startedAt: number;
	workers: WorkerHealth[];
	/** Number of guest sockets connected to the relay. */
	guests: number;
	stalledAfterMs: number;
}

export interface PushSubscriptionRequest {
	/** Web Push subscription as produced by PushManager.subscribe(). */
	endpoint: string;
	keys: { p256dh: string; auth: string };
	/** Human label shown in settings, e.g. "iPhone". */
	label?: string;
}

export type PushReason =
	| "turn-finished"
	| "needs-answer"
	| "needs-approval"
	| "worker-crashed"
	| "overnight-complete"
	| "overnight-deadline"
	| "overnight-blocked";

/** `GET /api/push/public-key` answers with the daemon's VAPID application server key (base64url). */
export interface PushPublicKeyResponse {
	publicKey: string;
}

/** `DELETE /api/push/subscribe` body (400 otherwise; 204 even when the endpoint was not stored). */
export interface PushUnsubscribeRequest {
	endpoint: string;
}

/**
 * Push endpoints: `GET /api/push/public-key`, `POST /api/push/subscribe` (PushSubscriptionRequest, 204),
 * `DELETE /api/push/subscribe` (PushUnsubscribeRequest, 204), `POST /api/push/test` (sends a test
 * notification to every stored subscription, 204; 409 when none is stored; 502 when subscriptions exist
 * but no push service accepted it).
 * Notification payload JSON sent to the service worker:
 */
export interface PushPayload {
	reason: PushReason;
	sessionId: string;
	title: string;
	body: string;
	/** Stable per session and reason so a repeat replaces instead of stacking: `${sessionId}:${reason}`. */
	tag: string;
	/** Path the notification opens, e.g. `/#session=<sessionId>`. */
	url: string;
	/**
	 * For `needs-answer` / `needs-approval` on a one-tap `select`: up to 3 option labels shown as notification actions,
	 * with the open question's id and a single-use token. Answer with `POST /api/push/answer`
	 * `{ token, value }` (value = one of `choices`); the token expires with the question or after 30 minutes.
	 */
	choices?: string[];
	reqId?: string;
	answerToken?: string;
}

/** `POST /api/push/answer`: answer the open question a notification showed, with that notification's token. */
export interface PushAnswerRequest {
	token: string;
	value: string;
}

export interface ApiError {
	error: string;
	code: "bad-request" | "not-found" | "conflict" | "unauthorized" | "forbidden" | "internal";
	sleepCandidate?: SleepCandidate;
}

export * from "./worker";
export * from "./features";
export * from "./wave2";
export * from "./wave3";
export * from "./overnight";
export * from "./wave4";
export * from "./claude-import";
